    rc |= expect_true("partial-hop-clears-rx-tone", rx_tone_publication_cleared(state, partial_hop_tone_generation));
    g_rigctl_setfreq_ok = 0;
    g_rtl_tune_result = RTL_STREAM_TUNE_OK;
