    rc |= test_live_loop_counts_only_checked_frames();
    rc |= test_legacy_step_landing_after_a_rigctl_move_and_under_a_hold();
    rc |= test_legacy_step_with_no_row_reopens_its_windows();
    rc |= test_untyped_resume_waits_for_its_row();
